const char* set_german_ini = (const char*) temp_binary_data_4;


const char* getNamedResource (const char* resourceNameUTF8, int& numBytes);
const char* getNamedResource (const char* resourceNameUTF8, int& numBytes)
{
    unsigned int hash = 0;

    if (resourceNameUTF8 != nullptr)
        while (*resourceNameUTF8 != 0)
            hash = 31 * hash + (unsigned int) *resourceNameUTF8++;

    switch (hash)
    {
        case 0xdfef1ad0:  numBytes = 1420609; return Anleitung_pdf;
        case 0x6567d151:  numBytes = 145999; return dawnotes_png;
        case 0xae93b283:  numBytes = 4286; return dawnnotes_ico;
        case 0x94871123:  numBytes = 127257; return header_banner_gif;
        case 0x8a4ae1a8:  numBytes = 18729; return set_german_ini;
        default: break;
    }

    numBytes = 0;
    return nullptr;
}

const char* namedResourceList[] =
{
    "Anleitung_pdf",
    "dawnotes_png",
    "dawnnotes_ico",
    "header_banner_gif",
    "set_german_ini"
};

const char* originalFilenames[] =
{
    "Anleitung.pdf",
    "dawnotes.png",
    "dawnnotes.ico",
    "header_banner.gif",
    "set_german.ini"
};

const char* getNamedResourceOriginalFilename (const char* resourceNameUTF8);
const char* getNamedResourceOriginalFilename (const char* resourceNameUTF8)
{
    for (unsigned int i = 0; i < (sizeof (namedResourceList) / sizeof (namedResourceList[0])); ++i)
        if (strcmp (namedResourceList[i], resourceNameUTF8) == 0)
            return originalFilenames[i];

    return nullptr;
}

